#include "platform/openvr/d3d_overlay_renderer.hpp"
#include <windows.h>
#include <d3d11.h>
#include <d2d1.h>
#include <dwrite.h>
#include <dxgi.h>
#include <wrl/client.h>
#include <algorithm>
#include <map>
namespace bailout::platform::openvr { using Microsoft::WRL::ComPtr;
struct D3dOverlayRenderer::Impl{
 struct Surface{uint32_t w=0,h=0;ComPtr<ID3D11Texture2D> texture;ComPtr<ID2D1RenderTarget> target;};
 ComPtr<ID3D11Device> device;ComPtr<ID3D11DeviceContext> context;ComPtr<ID2D1Factory> d2d;ComPtr<IDWriteFactory> write;ComPtr<IDWriteTextFormat> title,body,button;std::map<std::string,Surface> surfaces;std::string error;
 ComPtr<ID2D1SolidColorBrush> brush(ID2D1RenderTarget* t,D2D1_COLOR_F c){ComPtr<ID2D1SolidColorBrush>b;t->CreateSolidColorBrush(c,&b);return b;}
};
D3dOverlayRenderer::D3dOverlayRenderer():impl_(std::make_unique<Impl>()){}D3dOverlayRenderer::~D3dOverlayRenderer()=default;
bool D3dOverlayRenderer::initialize(){UINT flags=D3D11_CREATE_DEVICE_BGRA_SUPPORT;D3D_FEATURE_LEVEL got{};constexpr D3D_FEATURE_LEVEL levels[]={D3D_FEATURE_LEVEL_11_1,D3D_FEATURE_LEVEL_11_0,D3D_FEATURE_LEVEL_10_1};HRESULT hr=D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,flags,levels,3,D3D11_SDK_VERSION,&impl_->device,&got,&impl_->context);if(FAILED(hr))hr=D3D11CreateDevice(nullptr,D3D_DRIVER_TYPE_WARP,nullptr,flags,levels,3,D3D11_SDK_VERSION,&impl_->device,&got,&impl_->context);if(FAILED(hr)){impl_->error="D3D11CreateDevice failed";return false;}if(FAILED(D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED,impl_->d2d.GetAddressOf()))||FAILED(DWriteCreateFactory(DWRITE_FACTORY_TYPE_SHARED,__uuidof(IDWriteFactory),reinterpret_cast<IUnknown**>(impl_->write.GetAddressOf())))){impl_->error="Direct2D/DirectWrite initialization failed";return false;}impl_->write->CreateTextFormat(L"Segoe UI",nullptr,DWRITE_FONT_WEIGHT_SEMI_BOLD,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,46,L"",&impl_->title);impl_->write->CreateTextFormat(L"Segoe UI",nullptr,DWRITE_FONT_WEIGHT_NORMAL,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,27,L"",&impl_->body);impl_->write->CreateTextFormat(L"Segoe UI",nullptr,DWRITE_FONT_WEIGHT_SEMI_BOLD,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,30,L"",&impl_->button);return true;}
bool D3dOverlayRenderer::create_surface(const std::string& id,uint32_t w,uint32_t h){D3D11_TEXTURE2D_DESC d{};d.Width=w;d.Height=h;d.MipLevels=1;d.ArraySize=1;d.Format=DXGI_FORMAT_B8G8R8A8_UNORM;d.SampleDesc.Count=1;d.Usage=D3D11_USAGE_DEFAULT;d.BindFlags=D3D11_BIND_RENDER_TARGET|D3D11_BIND_SHADER_RESOURCE;Impl::Surface s{w,h};if(FAILED(impl_->device->CreateTexture2D(&d,nullptr,&s.texture)))return false;ComPtr<IDXGISurface> dxgi;if(FAILED(s.texture.As(&dxgi)))return false;auto props=D2D1::RenderTargetProperties(D2D1_RENDER_TARGET_TYPE_DEFAULT,D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM,D2D1_ALPHA_MODE_PREMULTIPLIED));if(FAILED(impl_->d2d->CreateDxgiSurfaceRenderTarget(dxgi.Get(),&props,&s.target)))return false;impl_->surfaces[id]=std::move(s);return true;}
bool D3dOverlayRenderer::render(const std::string& id,const SurfaceModel& m){auto it=impl_->surfaces.find(id);if(it==impl_->surfaces.end())return false;auto& s=it->second;auto*t=s.target.Get();auto white=impl_->brush(t,D2D1::ColorF(0.96f,0.98f,1,1));auto muted=impl_->brush(t,D2D1::ColorF(0.69f,0.74f,0.82f,1));auto accent=impl_->brush(t,D2D1::ColorF(0.15f,0.68f,0.88f,1));auto panel=impl_->brush(t,D2D1::ColorF(0.035f,0.055f,0.085f,0.94f));auto hover=impl_->brush(t,D2D1::ColorF(0.12f,0.34f,0.45f,1));auto normal=impl_->brush(t,D2D1::ColorF(0.08f,0.15f,0.22f,1));t->BeginDraw();t->Clear(D2D1::ColorF(0,0,0,0));t->FillRoundedRectangle(D2D1::RoundedRect(D2D1::RectF(8,8,float(s.w-8),float(s.h-8)),24,24),panel.Get());t->DrawTextW(m.title.c_str(),static_cast<UINT32>(m.title.size()),impl_->title.Get(),D2D1::RectF(42,30,float(s.w-42),100),white.Get());t->DrawTextW(m.body.c_str(),static_cast<UINT32>(m.body.size()),impl_->body.Get(),D2D1::RectF(42,105,float(s.w-42),float(s.h-105)),muted.Get());if(m.progress>0){float right=42+(s.w-84)*std::clamp(m.progress,0.0f,1.0f);t->FillRoundedRectangle(D2D1::RoundedRect(D2D1::RectF(42,float(s.h-38),right,float(s.h-24)),7,7),accent.Get());}if(!m.left_button.empty()){auto r=D2D1::RoundedRect(D2D1::RectF(42,float(s.h-112),float(s.w/2-12),float(s.h-54)),12,12);t->FillRoundedRectangle(r,m.left_hover?hover.Get():normal.Get());t->DrawTextW(m.left_button.c_str(),static_cast<UINT32>(m.left_button.size()),impl_->button.Get(),r.rect,white.Get());}if(!m.right_button.empty()){auto r=D2D1::RoundedRect(D2D1::RectF(float(s.w/2+12),float(s.h-112),float(s.w-42),float(s.h-54)),12,12);t->FillRoundedRectangle(r,m.right_hover?hover.Get():normal.Get());t->DrawTextW(m.right_button.c_str(),static_cast<UINT32>(m.right_button.size()),impl_->button.Get(),r.rect,white.Get());}return SUCCEEDED(t->EndDraw());}
void* D3dOverlayRenderer::texture(const std::string& id)const{auto it=impl_->surfaces.find(id);return it==impl_->surfaces.end()?nullptr:it->second.texture.Get();}const std::string& D3dOverlayRenderer::error()const{return impl_->error;}
}
